def affected(class_name, extensions) -> bool:
    if not extensions:
        return False
    o = [sum(c.isupper() for c in e) - sum(c.islower() for c in e) for e in extensions]
    m = [sum(c.isupper() for c in e) - sum(not c.islower() for c in e) for e in extensions]
    return o.index(max(o)) != m.index(max(m))
